function downloadFile(name,content,mime){const url=URL.createObjectURL(new Blob([content],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportProgress(){downloadFile('meu-progresso-computacao.json',JSON.stringify(state,null,2),'application/json');toast('Arquivo de progresso preparado para salvar.')}
function normalImported(p){const n=fresh();n.name=String(p.name||'').slice(0,50);n.createdAt=Number.isFinite(p.createdAt)?p.createdAt:Date.now();n.mastered=[...new Set((Array.isArray(p.mastered)?p.mastered:[]).filter(x=>Number.isInteger(x)&&x>=0&&x<window.COURSE.length))];n.unlockedPhase=Math.max(0,Math.min(window.COURSE.length-1,Number.isInteger(p.unlockedPhase)?p.unlockedPhase:0));n.unlockedPhase=Math.max(n.unlockedPhase,...n.mastered.map(x=>Math.min(12,x+1)));n.completedLessons={};for(let i=0;i<window.COURSE.length;i++)for(let j=0;j<3;j++)if(p.completedLessons?.[doneKey(i,j)]===true)n.completedLessons[doneKey(i,j)]=true;n.attempts={};if(p.attempts&&typeof p.attempts==='object')for(const [k,v] of Object.entries(p.attempts).slice(0,1000))if(v&&typeof v==='object')n.attempts[k.slice(0,100)]={attempts:Math.max(0,Number(v.attempts)||0),errors:Math.max(0,Number(v.errors)||0)};n.xp=Math.max(0,Math.min(10000000,Number(p.xp)||0));n.lastPhase=Math.max(0,Math.min(12,Number(p.lastPhase)||0));n.lastRoute='inicio';n.srs={};if(p.srs&&typeof p.srs==='object')for(const [k,v] of Object.entries(p.srs)){if(!/^term:\d+$/.test(k)||!v||typeof v!=='object')continue;const idx=Number(k.slice(5));if(idx>=window.GLOSSARY.length)continue;n.srs[k]={box:Math.max(0,Math.min(3,Number(v.box)||0)),due:Math.max(0,Math.min(8640000000000000,Number(v.due)||Date.now())),seen:Math.max(0,Number(v.seen)||0),lapses:Math.max(0,Number(v.lapses)||0)}}n.reflections={};if(p.reflections&&typeof p.reflections==='object')for(const [k,v] of Object.entries(p.reflections).slice(0,1000))n.reflections[k.slice(0,120)]=String(v).slice(0,10000);n.quizHistory=Array.isArray(p.quizHistory)?p.quizHistory.slice(-50).filter(x=>x&&Number.isInteger(x.phase)&&x.phase>=0&&x.phase<13).map(x=>({phase:x.phase,score:Math.max(0,Math.min(4,Number(x.score)||0)),passed:!!x.passed,date:Number(x.date)||Date.now()})):[];n.projectChecks={};if(p.projectChecks&&typeof p.projectChecks==='object')for(let i=0;i<6;i++)n.projectChecks[i]=p.projectChecks[i]===true;return n}
