let cpuState=null;const CPU_PROGRAM=[{op:'SET',a:5,text:'SET A 5'},{op:'ADD',a:3,text:'ADD A 3'},{op:'STORE',addr:0,reg:'A',text:'STORE 0 A'},{op:'SUB',a:2,text:'SUB A 2'},{op:'HALT',text:'HALT'}];function resetCPU(){cpuState={a:0,memory:{},pc:0,halted:false,trace:[]};updateCPU()}function ensureCPU(){if(!cpuState)resetCPU()}
function updateCPU(){const regs=$('#cpu-registers'),desc=$('#cpu-description'),tb=$('#cpu-trace');if(!regs||!tb||!cpuState)return;regs.innerHTML=`<div><span>Registrador A</span><strong>${cpuState.a}</strong></div><div><span>Memória[0]</span><strong>${cpuState.memory[0]===undefined?'—':cpuState.memory[0]}</strong></div><div><span>Contador de programa</span><strong>${cpuState.pc}</strong></div>`;desc.textContent=cpuState.halted?'HALT executado: a máquina didática parou.':cpuState.pc===0&&cpuState.trace.length===0?'Programa pronto para iniciar.':`Última instrução: ${CPU_PROGRAM[Math.max(0,cpuState.pc-1)]?.text||'—'}. O estado foi atualizado.`;tb.innerHTML=CPU_PROGRAM.map((x,i)=>`<tr class="${i===cpuState.pc&&!cpuState.halted?'current':''}"><td>${i}</td><td>${esc(x.text)}</td><td>${cpuState.trace.includes(i)?'executada':i===cpuState.pc&&!cpuState.halted?'próxima':'aguardando'}</td></tr>`).join('')}
function cpuStep(){ensureCPU();if(cpuState.halted){toast('A CPU didática já parou. Reinicie para repetir.');return}const pc=cpuState.pc,ins=CPU_PROGRAM[pc];if(!ins){cpuState.halted=true;updateCPU();return}cpuState.trace.push(pc);if(ins.op==='SET')cpuState.a=ins.a;if(ins.op==='ADD')cpuState.a+=ins.a;if(ins.op==='SUB')cpuState.a-=ins.a;if(ins.op==='STORE')cpuState.memory[ins.addr]=cpuState.a;if(ins.op==='HALT')cpuState.halted=true;else cpuState.pc++;updateCPU();if(cpuState.halted)toast(`Programa terminou: A=${cpuState.a}, memória[0]=${cpuState.memory[0]}.`)}
function refreshDemoForRoute(r){if(r.name==='fase'&&Number(r.args[0])===7&&Number(r.args[1])===1){ensureCPU();updateCPU()}if(r.name==='fase'&&Number(r.args[0])===3&&Number(r.args[1])===1)updateGate();if(r.name==='fase'&&Number(r.args[0])===5&&Number(r.args[1])===0)updateAdder()}
function updateGate(){const a=Number($('#gate-a')?.value||0),b=Number($('#gate-b')?.value||0),el=$('#gate-results');if(!el)return;const values=[a&b,a|b,a^b,1-(a&b),1-(a|b),1-a],labels=['AND · E','OR · OU','XOR · OU exclusivo','NAND · NÃO-E','NOR · NÃO-OU','NOT A · NÃO A'];el.innerHTML=values.map((v,i)=>`<div class="gate-cell"><small>${labels[i]}</small><strong>${v}</strong></div>`).join('')}
