function gradeCurrentCard(rating){const i=reviewQueue[reviewIndex];if(i===undefined)return;const id=termId(i),cur=state.srs[id]||{box:0,due:Date.now(),seen:0,lapses:0};let box=cur.box,due;if(rating===0){box=0;due=Date.now()+15*60*1000;cur.lapses=(cur.lapses||0)+1;toast('Tudo bem: este cartão volta em cerca de 15 minutos.')}else{box=Math.min(3,(cur.box||0)+1);const days=rating===1?1:INTERVALS[box];due=Date.now()+days*86400000;toast(rating===1?'Agendado para amanhã.':`Próxima revisão em ${days} dia(s).`)}state.srs[id]={box,due,seen:(cur.seen||0)+1,lapses:cur.lapses||0};state.xp+=rating===2?2:rating===1?1:0;reviewIndex++;reviewRevealed=false;if(reviewIndex>=reviewQueue.length){reviewQueue=[];reviewIndex=0;toast('Rodada de revisão concluída.')}save();render()}
function finishQuiz(p){if(!currentQuiz||currentQuiz.phase!==p||currentQuiz.stage!=='reflection')return;const text=$('#reflection-text')?.value.trim()||'',checked=$('#reflection-selfcheck')?.checked||false;if(text.length<40){toast(`Sua explicação tem ${text.length} caracteres. Escreva pelo menos 40, incluindo um exemplo.`);$('#reflection-text')?.focus();return}if(!checked){toast('Marque a autoavaliação depois de tentar explicar sem consultar.');return}state.reflections[`phase:${p}`]=text;const score=currentQuiz.items.filter(x=>x.correct).length;const passed=score>=3;currentQuiz.score=score;currentQuiz.passed=passed;currentQuiz.finished=true;state.quizHistory.push({phase:p,score,passed,date:Date.now()});state.quizHistory=state.quizHistory.slice(-50);if(passed){if(!state.mastered.includes(p))state.mastered.push(p);state.unlockedPhase=Math.max(state.unlockedPhase,Math.min(12,p+1));state.xp+=50;activatePhaseCards(p);toast(p===12?'Parabéns — projeto final desbloqueado!':'Fase dominada; a próxima foi desbloqueada.')}else toast('Você precisa acertar pelo menos 3 de 4. Revise o feedback e tente novamente.');save();render()}
function safeCopy(text){if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(text).then(()=>toast('Copiado.')).catch(()=>fallbackCopy(text));}else fallbackCopy(text)}function fallbackCopy(text){const t=document.createElement('textarea');t.value=text;t.style.position='fixed';t.style.opacity='0';document.body.appendChild(t);t.select();let ok=false;try{ok=document.execCommand('copy')}catch{}t.remove();toast(ok?'Copiado.':'Não foi possível copiar automaticamente; selecione o texto e copie manualmente.')}
